return ['domain'=>'wpml-import','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'WPML Export and Import 5.0.0','pot-creation-date'=>'2026-09-15T17:43:02+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['WPML Export and Import'=>'WPML Export and Import','https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/'=>'https://wpml.org/documentation/wpml-core-and-add-on-plugins/wpml-export-and-import/','A multipurpose plugin to export and import multilingual content.'=>'Wielozadaniowa wtyczka do eksportu i importu treści wielojęzycznych.','OnTheGoSystems'=>'OnTheGoSystems','http://www.onthegosystems.com'=>'http://www.onthegosystems.com','The import trigger no longer accepts the key in the URL. Send it in a POST body.'=>'Wyzwalacz importu nie akceptuje już klucza w adresie URL. Wyślij go w treści żądania (body) POST.','Method Not Allowed'=>'Niedozwolona metoda','Unauthorized'=>'Brak autoryzacji','No items to process'=>'Brak elementów do przetworzenia','No Content'=>'Brak treści','Import process completed'=>'Proces importu zakończony','Success'=>'Sukces','Import process failed'=>'Proces importu nie powiódł się','Internal Server Error'=>'Wewnętrzny błąd serwera','%1$s: %2$d item could not be processed and was skipped.'=>'%1$s: %2$d element nie mógł zostać przetworzony i został pominięty.' . "\0" . '%1$s: %2$d elementy nie mogły zostać przetworzone i zostały pominięte.' . "\0" . '%1$s: %2$d elementów nie mogło zostać przetworzonych i zostało pominiętych.','Cleaning Up Post Data'=>'Oczyszczanie danych wpisów','Removing temporary and import-related post meta data.'=>'Usuwanie tymczasowych i związanych z importem metadanych wpisów.','Cleaning Up Term Data'=>'Oczyszczanie danych terminów','Removing temporary and import-related term meta data.'=>'Usuwanie tymczasowych i związanych z importem metadanych terminów.','Connecting Post Image Attachments'=>'Łączenie załączników obrazów wpisów','Updating thumbnail and gallery attachment IDs on translated posts, products, and CPTs to point to their translated equivalents.'=>'Aktualizowanie identyfikatorów ID załączników miniatur i galerii w przetłumaczonych wpisach, produktach i własnych typach wpisów (CPT), aby wskazywały na ich przetłumaczone odpowiedniki.','Connecting Inline Term Translations'=>'Łączenie tłumaczeń terminów w treści','Scanning posts with a single taxonomy term in order to identify and connect the terms assigned to these posts with their translations.'=>'Skanowanie wpisów z pojedynczym terminem taksonomii w celu zidentyfikowania i połączenia terminów przypisanych do tych wpisów z ich tłumaczeniami.','Deleting Obsolete Original Terms'=>'Usuwanie przestarzałych terminów oryginalnych','Removing original terms that are no longer needed after creating duplicates for same-named terms. Ensuring no posts are linked to these original terms.'=>'Usuwanie oryginalnych terminów, które nie są już potrzebne po utworzeniu duplikatów dla terminów o tej samej nazwie. Zapewnienie, że żadne wpisy nie są powiązane z tymi oryginalnymi terminami.','Duplicating Terms with Shared Names Across Languages'=>'Duplikowanie terminów o wspólnych nazwach w różnych językach','Creating duplicates in the correct language for terms that share the same name across languages, but belong to posts in different languages.'=>'Tworzenie duplikatów w odpowiednim języku dla terminów, które mają tę samą nazwę w różnych językach, ale należą do wpisów w różnych językach.','Fixing Imported Post Slugs'=>'Naprawianie uproszczonych nazw (slugów) zaimportowanych wpisów','Regenerating translated post slugs to prevent conflicts with the originals.'=>'Regenerowanie uproszczonych nazw (slugów) przetłumaczonych wpisów, aby zapobiec konfliktom z oryginałami.','Clearing Translations Cache'=>'Czyszczenie pamięci podręcznej tłumaczeń','Invalidating the persistent cache so it can be regenerated.'=>'Unieważnianie trwałej pamięci podręcznej, aby mogła zostać zregenerowana.','Marking Parent Terms for Connection'=>'Oznaczanie terminów nadrzędnych do połączenia','Collecting parent terms to connect their translations in the next step.'=>'Zbieranie terminów nadrzędnych w celu połączenia ich tłumaczeń w następnym kroku.','Connecting Posts with Correct Term Translations'=>'Łączenie wpisów z prawidłowymi tłumaczeniami terminów','Ensuring posts are connected to terms in the correct language, especially if you have the same term names across languages.'=>'Zapewnienie, że wpisy są połączone z terminami w odpowiednim języku, zwłaszcza jeśli masz takie same nazwy terminów w różnych językach.','Sending Posts for Automatic Translation'=>'Wysyłanie wpisów do automatycznego tłumaczenia','Creating automatic translation jobs for posts flagged for auto-translation in the exported data.'=>'Tworzenie zadań automatycznego tłumaczenia dla wpisów oznaczonych do automatycznego tłumaczenia w wyeksportowanych danych.','Setting Attachments\' Language'=>'Ustawianie języka załączników','Assigning a language to imported attachments.'=>'Przypisywanie języka do zaimportowanych załączników.','Updating Final Post Status'=>'Aktualizowanie końcowego statusu wpisu','Setting the post status based on the "_wpml_import_after_process_post_status" field from the import file (if provided).'=>'Ustawianie statusu wpisu na podstawie pola „_wpml_import_after_process_post_status” z pliku importu (jeśli zostało podane).','Identifying Inline Term Languages'=>'Identyfikowanie języków terminów w treści','Identifying and setting the language of terms created during post imports.'=>'Identyfikowanie i ustawianie języka terminów utworzonych podczas importu wpisów.','Setting Posts’ Language'=>'Ustawianie języka wpisów','Connecting posts to the default language and translations.'=>'Łączenie wpisów z językiem domyślnym i tłumaczeniami.','Setting Terms’ Language'=>'Ustawianie języka terminów','Connecting taxonomy terms to the default (original) language and translations.'=>'Łączenie terminów taksonomii z domyślnym (oryginalnym) językiem i tłumaczeniami.','Setting Parent Terms\' Language'=>'Ustawianie języka terminów nadrzędnych','Assigning language to parent taxonomy terms that don\'t have one, based on the language assigned to their children.'=>'Przypisywanie języka do nadrzędnych terminów taksonomii, które go nie posiadają, na podstawie języka przypisanego do ich elementów podrzędnych.','Migrating your multilingual site? Remember to also install %s on your new site before importing your content so we can restore all the translations.'=>'Migrujesz swoją witrynę wielojęzyczną? Pamiętaj, aby przed zaimportowaniem treści zainstalować %s również w nowej witrynie, abyśmy mogli przywrócić wszystkie tłumaczenia.','Migrating your multilingual shop? With %1$s and %2$s you can transfer your translated content to a new site, including cross-sells, up-sells, and product attributes.'=>'Migrujesz swój sklep wielojęzyczny? Dzięki %1$s i %2$s możesz przenieść przetłumaczoną treść do nowej witryny, w tym sprzedaż krzyżową, sprzedaż dodatkową i atrybuty produktów.','Migrating your multilingual shop? Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Migrujesz swój sklep wielojęzyczny? Pamiętaj, aby przed zaimportowaniem treści zainstalować %1$s i %2$s w nowej witrynie, abyśmy mogli przywrócić wszystkie tłumaczenia.','Looking to import your multilingual content? Remember to install %s in your original site before exporting its content so we can import all the translations here.'=>'Chcesz zaimportować swoją wielojęzyczną treść? Pamiętaj, aby zainstalować %s w oryginalnej witrynie przed wyeksportowaniem jej treści, abyśmy mogli zaimportować tutaj wszystkie tłumaczenia.','Looking to import your multilingual content? Install %1$s on this site.'=>'Chcesz zaimportować swoją wielojęzyczną treść? Zainstaluj %1$s w tej witrynie.','Remember to also enable %2$s and %3$s in your original shop before exporting its content so we can import all the translations here.'=>'Pamiętaj, aby przed wyeksportowaniem treści włączyć również %2$s i %3$s w oryginalnym sklepie, abyśmy mogli zaimportować tutaj wszystkie tłumaczenia.','Looking to import your multilingual content? Remember to enable %1$s and %2$s in your original shop before exporting its content so we can import all the translations here.'=>'Chcesz zaimportować swoją wielojęzyczną treść? Pamiętaj, aby przed wyeksportowaniem treści włączyć %1$s i %2$s w oryginalnym sklepie, abyśmy mogli zaimportować tutaj wszystkie tłumaczenia.','WooCommerce Multilingual'=>'WooCommerce Multilingual','Switch to all languages'=>'Przełącz na wszystkie języki','Linking Product Attribute Translations'=>'Łączenie tłumaczeń atrybutów produktów','Connecting product attributes to their translations based on associated product variations.'=>'Łączenie atrybutów produktów z ich tłumaczeniami na podstawie powiązanych wariantów produktów.','Updating Related Products On Translations'=>'Aktualizowanie powiązanych produktów w tłumaczeniach','Setting up-sells, cross-sells and grouped products references in the right language.'=>'Ustawianie odniesień do sprzedaży dodatkowej, sprzedaży krzyżowej i produktów grupowych w odpowiednim języku.','Importing Custom Attribute Labels'=>'Importowanie własnych etykiet atrybutów','Importing labels for product-specific (custom) attributes from the exported data.'=>'Importowanie etykiet dla atrybutów specyficznych dla produktu (własnych) z wyeksportowanych danych.','You are about to export all your products in all languages at once.'=>'Zamierzasz wyeksportować wszystkie swoje produkty we wszystkich językach naraz.','Remember to install %1$s and %2$s on your new site before importing your content so we can restore all the translations.'=>'Pamiętaj, aby przed zaimportowaniem treści zainstalować %1$s i %2$s w nowej witrynie, abyśmy mogli przywrócić wszystkie tłumaczenia.','You are about to export your products in %s.'=>'Zamierzasz wyeksportować swoje produkty w języku %s.','Registering Product Attributes'=>'Rejestrowanie atrybutów produktów','Identifying and registering attributes created during product imports for translation.'=>'Identyfikowanie i rejestrowanie do tłumaczenia atrybutów utworzonych podczas importu produktów.','Identifying Product Attribute Languages'=>'Identyfikowanie języków atrybutów produktów','Identifying and setting the language of attributes created during product imports.'=>'Identyfikowanie i ustawianie języka atrybutów utworzonych podczas importu produktów.','Export and Import'=>'Eksport i import','I’m using the built-in %s export/import tool'=>'Używam wbudowanego narzędzia do eksportu/importu %s','I’m using %s plugin'=>'Używam wtyczki %s','(%1$d/%2$d items)'=>'(%1$d/%2$d elementów)','%d skipped'=>'Pominięto: %d','(no items)'=>'(brak elementów)','Counting items...'=>'Liczenie elementów...','First, tell us how you’re going to create the content that you’ll be importing:'=>'Najpierw powiedz nam, w jaki sposób zamierzasz utworzyć treść, którą będziesz importować:','Continue'=>'Kontynuuj','I’m using %1$s and %2$s plugins'=>'Używam wtyczek %1$s i %2$s','I’m using a different method to export from this site'=>'Używam innej metody eksportu z tej witryny','I’m exporting the content from this site'=>'Eksportuję treść z tej witryny','I’m exporting the content from a different website or system'=>'Eksportuję treść z innej strony internetowej lub systemu','Before importing, add language columns to your content'=>'Przed importowaniem dodaj kolumny językowe do swojej treści','Make sure that your import file includes the following columns (custom fields) with language information:'=>'Upewnij się, że plik importu zawiera następujące kolumny (własne pola) z informacjami o języku:','%s: A value that’s the same for all the translations of each item. In e-commerce sites this will often be the SKU.'=>'%s: Wartość, która jest taka sama dla wszystkich tłumaczeń każdego elementu. W witrynach e-commerce często będzie to SKU.','%s: The language code for each item.'=>'%s: Kod języka dla każdego elementu.','And, you can include these two columns if needed:'=>'W razie potrzeby możesz również dołączyć te dwie kolumny:','%s: If this item is a translation, set this column to the code of the source language. If it’s not a translation, keep it empty.'=>'%s: Jeśli ten element jest tłumaczeniem, ustaw tę kolumnę na kod języka źródłowego. Jeśli nie jest tłumaczeniem, pozostaw ją pustą.','%s: Set to “draft” or “published” to determine the publishing status of the post after adjusting languages. Usually, this value will be “published”.'=>'%s: Ustaw na „draft” (szkic) lub „published” (opublikowany), aby określić status publikacji wpisu po dostosowaniu języków. Zazwyczaj wartością tą będzie „published”.','Here is an example of importing two items, into your site’s languages (%s):'=>'Oto przykład importowania dwóch elementów do języków Twojej witryny (%s):','Once you’ve added language columns to your multilingual content file, import it to your site using whatever import plugin you prefer.'=>'Po dodaniu kolumn językowych do pliku z treścią wielojęzyczną zaimportuj go do swojej witryny za pomocą dowolnej preferowanej wtyczki do importu.','Before importing, your content needs language information'=>'Przed importowaniem Twoja treść wymaga informacji o języku','%s will add the necessary language information to your export.'=>'%s doda niezbędne informacje o języku do Twojego eksportu.','Import your multilingual content file into the site using whatever import plugin you prefer.'=>'Zaimportuj plik z treścią wielojęzyczną do witryny za pomocą dowolnej preferowanej wtyczki do importu.','Use your favorite import plugin'=>'Użyj swojej ulubionej wtyczki do importu','After you import the content, it will still not show the correct language information. So, we recommend that you import new content as Drafts. If you’re importing updates, you can keep already-published content as published.'=>'Po zaimportowaniu treści nadal nie będzie ona wyświetlać poprawnych informacji o języku. Dlatego zalecamy importowanie nowej treści jako szkice. Jeśli importujesz aktualizacje, możesz zachować już opublikowaną treść jako opublikowaną.','Return here, to %s, to set languages and connect translations'=>'Wróć tutaj, do %s, aby ustawić języki i połączyć tłumaczenia','When you visit this page after you’ve imported content with language information, you’ll be able to run %s to apply languages and connect translations.'=>'Gdy odwiedzisz tę stronę po zaimportowaniu treści z informacjami o języku, będziesz mieć możliwość uruchomienia %s, aby zastosować języki i połączyć tłumaczenia.','Already imported and still seeing this screen? %1$sTroubleshooting %2$s%3$s.'=>'Treść została już zaimportowana, a Ty nadal widzisz ten ekran? %1$sRozwiązywanie problemów %2$s%3$s.','How to Export and Import Content in Multiple Languages'=>'Jak eksportować i importować treści w wielu językach','%s is ready to update your imported content'=>'%s jest gotowy do zaktualizowania zaimportowanej treści','Good job. We see %1$d terms and %2$d posts that are imported and need language information.'=>'Dobra robota. Znaleźliśmy %1$d terminów i %2$d wpisów, które zostały zaimportowane i wymagają informacji o języku.','Good job. We see %d terms that are imported and need language information.'=>'Dobra robota. Znaleźliśmy %d terminów, które zostały zaimportowane i wymagają informacji o języku.','Good job. We see %d posts that are imported and need language information.'=>'Dobra robota. Znaleźliśmy %d wpisy, które zostały zaimportowane i wymagają informacji o języku.','Run WPML Import'=>'Uruchom WPML Import','Multilingual Import Complete'=>'Import wielojęzyczny zakończony']];